/**
 * The functions of Evolu's C core, which the binary exports for this package's
 * own bindings, typed as `CApi.ts` types SQLite's. The package's entry points
 * don't re-export this module, and {@link SqliteCExports} leaves these exports
 * out, so each function reads its export from `SqliteWasm.exports` through a
 * cast. The build guard hashes the export names, so a binary without them fails
 * to load.
 *
 * Generated by `scripts/generate.mts` from the metadata in
 * `scripts/bindings.mts`, with every wasm type checked against the binary's
 * pinned exports. Do not edit.
 *
 * @module
 */

import type { SqliteCExports } from "./CApi.ts";
import type { SqliteResultCode } from "./Constants.ts";
import type { CStringPtr, NullPtr, SqliteDbPtr, WasmPtr } from "./Pointer.ts";
import type { SqliteWasmDep } from "./Wasm.ts";

/** The functions of Evolu's C core as the wasm exports them. */
export interface EvoluCExports {
  readonly evolu_codec_register: (
    name: CStringPtr,
    inner_name: CStringPtr | NullPtr,
  ) => SqliteResultCode;
  readonly evolu_codec_open: (
    filename: CStringPtr,
    db: WasmPtr,
    vfs: CStringPtr,
    key: WasmPtr | NullPtr,
    flags: number,
  ) => SqliteResultCode;
  readonly evolu_codec_take_failure: (
    db: SqliteDbPtr | NullPtr,
    failure: WasmPtr,
  ) => SqliteResultCode;
  readonly evolu_core_register: (db: SqliteDbPtr) => SqliteResultCode;
  readonly evolu_skiplist_finalize: (db: SqliteDbPtr) => void;
}

/**
 * Registers a codec VFS named name over the VFS named inner_name, or the
 * default VFS when it's NULL, without making it the default. Returns SQLITE_OK,
 * also when a codec VFS of that name over the same inner VFS is registered
 * already, SQLITE_ERROR when there's no such inner VFS, SQLITE_MISUSE when
 * another VFS has the name or the inner VFS is a codec VFS, or SQLITE_NOMEM.
 *
 * Wasm type `i(ii)`, signature `["evolu_codec_register", "int", "string",
 * "string"]` from Evolu's metadata.
 */
export const evolu_codec_register = (
  deps: SqliteWasmDep,
): EvoluCExports["evolu_codec_register"] =>
  (deps.sqliteWasm.exports as SqliteCExports & EvoluCExports)
    .evolu_codec_register;

/**
 * Opens the database filename on the codec VFS named vfs, read-write, created
 * when missing, with extended result codes. With a 32-byte key, the database is
 * encrypted; with NULL, it's plaintext. Flags are 0, 1 to open SQLCipher 4's
 * files too, or 2 to keep the journal checksums over the plaintext; both, any
 * other bit, or a vfs that names no codec VFS return SQLITE_MISUSE with *db
 * NULL. As with sqlite3_open_v2, *db is set to the connection, unless memory
 * runs out, also when the open fails, and the caller closes it. Returns
 * SQLITE_MISUSE when a key was given but SQLite opened no database file through
 * a codec VFS, as for an in-memory database. Every connection it opens attaches
 * databases read-only and is set up by {@link evolu_core_register}, so it's
 * defensive and has Evolu's SQL functions.
 *
 * Wasm type `i(iiiii)`, signature `["evolu_codec_open", "int", "string", "**",
 * "string", "*", "int"]` from Evolu's metadata.
 */
export const evolu_codec_open = (
  deps: SqliteWasmDep,
): EvoluCExports["evolu_codec_open"] =>
  (deps.sqliteWasm.exports as SqliteCExports & EvoluCExports).evolu_codec_open;

/**
 * Moves the first failure the codec recorded for db's main database into the 8
 * bytes at failure and clears it: the failure's type, an i32 from 0 for none to
 * 3, at 0, and the page number, a u32, at 4. Returns SQLITE_OK, SQLITE_NOTFOUND
 * when the main database isn't open on a codec VFS, or SQLITE_MISUSE when db is
 * NULL.
 *
 * Wasm type `i(ii)`, signature `["evolu_codec_take_failure", "int", "sqlite3*",
 * "*"]` from Evolu's metadata.
 */
export const evolu_codec_take_failure = (
  deps: SqliteWasmDep,
): EvoluCExports["evolu_codec_take_failure"] =>
  (deps.sqliteWasm.exports as SqliteCExports & EvoluCExports)
    .evolu_codec_take_failure;

/**
 * Sets a connection up for Evolu, as {@link evolu_codec_open} does for every
 * connection it opens: makes it defensive (SQLITE_DBCONFIG_DEFENSIVE), so it
 * ignores PRAGMA writable_schema = ON, journal_mode = OFF and schema_version =
 * N, and registers the SQL functions of Evolu's timestamp skiplist and
 * evolu_core_version, which returns the core's version. Calling it again keeps
 * the statements the functions keep.
 *
 * Wasm type `i(i)`, signature `["evolu_core_register", "int", "sqlite3*"]` from
 * Evolu's metadata.
 */
export const evolu_core_register = (
  deps: SqliteWasmDep,
): EvoluCExports["evolu_core_register"] =>
  (deps.sqliteWasm.exports as SqliteCExports & EvoluCExports)
    .evolu_core_register;

/**
 * Finalizes the statements the skiplist functions keep on a connection, which a
 * later call prepares again, and does nothing on a connection without them.
 * sqlite3_close_v2 finalizes them too, but code that finalizes every statement
 * of a connection through sqlite3_next_stmt calls it first, since that would
 * finalize them behind the functions' back, and the close would then finalize
 * them again.
 *
 * Wasm type `v(i)`, signature `["evolu_skiplist_finalize", undefined,
 * "sqlite3*"]` from Evolu's metadata.
 */
export const evolu_skiplist_finalize = (
  deps: SqliteWasmDep,
): EvoluCExports["evolu_skiplist_finalize"] =>
  (deps.sqliteWasm.exports as SqliteCExports & EvoluCExports)
    .evolu_skiplist_finalize;
